#!/usr/bin/env python3
"""Build self-contained policies/v7_policy.py = V5 + night free-float v7."""
from pathlib import Path

root = Path(__file__).resolve().parents[1]
v5 = (root / "policies/v5_policy.py").read_text()

out = v5.replace(
    '"""V5 rule-based HVAC policy = V4 + per-zone economic target shift.\n\nGenerated by tools/build_v5.py; do not edit directly.\n"""',
    '"""V7 rule-based HVAC policy = V5 + night free-float with season-aware\npre-conditioning lead and a drift guard.\n\nGenerated by tools/build_v7.py; do not edit directly.\n"""',
)

v7 = '''

class V7Policy(V5Policy):
    """v5 economic target shift + night free-float.

    Instead of holding the building at the (shifted) band all night with the
    plant running, let it free-float and only run the plant during the final
    pre-conditioning window before comfort starts:
      * lead = 5h in the heating season (OAT below comfort centre),
        3h in the cooling season (measured on the first AHU's OAT sensor);
      * drift guard: if the worst zone band deficit exceeds 1.5K while the
        comfort start is within 12h, re-latch (behaves like v5 for
        fast-drifting/light-mass buildings; inert for heavy-mass ones).
    The v4g/v6 eco-edge hold is dropped: it is redundant with free-float and
    cost ~10% on minneapolis_1/b8-class buildings.
    """

    def __init__(self, building_meta_data, action_spec):
        super().__init__(building_meta_data, action_spec)
        self.ff_lead_heating_h = 5.0
        self.ff_lead_cooling_h = 3.0
        # Drift guard: backstop for fast-drifting buildings. Tuned per season:
        # inert on all observed winter scenarios; relaxed in cooling so mild
        # evening warm-up drift doesn't re-latch the chiller at peak hours.
        self.ff_guard_heating_k = 1.5
        self.ff_guard_heating_horizon_h = 12.0
        self.ff_guard_cooling_k = 2.5
        self.ff_guard_cooling_horizon_h = 8.0

    def _plant_override(self, st, plant_on, comfort_now, t_next, hour, obs):
        if comfort_now:
            return True
        lo_d, hi_d = self.comfort_temp_window
        centre = 0.5 * (lo_d + hi_d)
        oat = None
        oat_idx = self.ahus[0]["oat_sensor_idx"] if self.ahus else None
        if oat_idx is not None:
            value = float(obs[oat_idx])
            if np.isfinite(value):
                oat = self._denorm(value, self.oat_mean, self.oat_std)
        if oat is None or oat < centre:
            lead = self.ff_lead_heating_h
        else:
            lead = self.ff_lead_cooling_h
        if t_next <= lead:
            return True
        if oat is None or oat < centre:
            g_k, g_h = self.ff_guard_heating_k, self.ff_guard_heating_horizon_h
        else:
            g_k, g_h = self.ff_guard_cooling_k, self.ff_guard_cooling_horizon_h
        if t_next <= g_h and self._worst_deficit(obs) > g_k:
            return True
        return False


V7PolicyStandalone = V7Policy
'''
out = out.rstrip() + v7
(root / "policies/v7_policy.py").write_text(out)
print("wrote policies/v7_policy.py", len(out), "chars")
